add_action( 'woocommerce_cart_totals_before_order_total', 'perfectpixel_cart_total_weight_row' );
add_action( 'woocommerce_review_order_before_order_total', 'perfectpixel_cart_total_weight_row' );

function perfectpixel_cart_total_weight_row() {
	if ( ! WC()->cart ) {
		return;
	}
	$weight = (float) WC()->cart->get_cart_contents_weight();
	if ( $weight <= 0 ) {
		return;
	}
	printf(
		'<tr class="perfectpixel-cart-weight"><th>%1$s</th><td data-title="%1$s">%2$s %3$s</td></tr>',
		esc_html( '{{weight_label}}' ),
		esc_html( wc_format_localized_decimal( wc_format_decimal( $weight, 2 ) ) ),
		esc_html( get_option( 'woocommerce_weight_unit' ) )
	);
}
